const items = $input.all();
const budgetItems = items.filter(i => i.json._source === 'budget');
const actualItems = items.filter(i => i.json._source === 'actual');

const budget = {};
for (const b of budgetItems) {
  budget[b.json.category] = Number(b.json.amount) || 0;
}

const actual = {};
for (const a of actualItems) {
  actual[a.json.category] = Number(a.json.amount) || 0;
}

const categories = [...new Set([...Object.keys(budget), ...Object.keys(actual)])];
const report = categories.map(cat => {
  const budgeted = budget[cat] || 0;
  const spent = actual[cat] || 0;
  const variance = budgeted - spent;
  const variancePct = budgeted > 0 ? Math.round((variance / budgeted) * 10000) / 100 : 0;
  return {
    category: cat,
    budgeted,
    actual: spent,
    variance,
    variancePercent: variancePct,
    status: variance >= 0 ? 'Under Budget' : 'Over Budget'
  };
});

const totalBudget = Object.values(budget).reduce((s, v) => s + v, 0);
const totalActual = Object.values(actual).reduce((s, v) => s + v, 0);

return [{ json: { report, totalBudget, totalActual, totalVariance: totalBudget - totalActual, month: new Date().toISOString().slice(0, 7) } }];

